const ZIP_NON_ALLIANCE = new Set(ZIP_ROUTING.nonAllianceZips);
const ZIP_UNLISTED_PICK = new Map();
const MAX_ASSIGN_MILES = 30;

function referralHref(zip) {
  const base = ZIP_ROUTING.referralUrl;
  if (!/^\d{5}$/.test(String(zip || ""))) return base;
  return base + "?loc=" + zip;
}

function routeZip(value) {
  const zip = String(value || "").trim();
  if (!/^\d{5}$/.test(zip)) return { kind: "invalid", zip };
  const alliance = ZIP_ROUTING.allianceZips[zip];
  if (alliance) {
    return {
      kind: alliance.length > 1 ? "overlap" : "alliance",
      zip,
      ids: alliance.slice(),
    };
  }
  if (ZIP_NON_ALLIANCE.has(zip)) return { kind: "referral", zip };
  const unlisted = ZIP_ROUTING.unlistedSoCal[zip];
  if (unlisted) {
    if (unlisted.d > MAX_ASSIGN_MILES) return { kind: "outside", zip };
    if (!ZIP_UNLISTED_PICK.has(zip)) {
      const ids = unlisted.o;
      ZIP_UNLISTED_PICK.set(zip, ids[Math.floor(Math.random() * ids.length)]);
    }
    return {
      kind: "unlisted",
      zip,
      id: ZIP_UNLISTED_PICK.get(zip),
      ids: unlisted.o.slice(),
      city: unlisted.c,
    };
  }
  return { kind: "outside", zip };
}

globalThis.ZIP_ROUTING = ZIP_ROUTING;
globalThis.routeZip = routeZip;
globalThis.referralHref = referralHref;
globalThis.MAX_ASSIGN_MILES = MAX_ASSIGN_MILES;
